const parser = new DOMParser();
const xmlDoc = parser.parseFromString($input.first().json.data, 'text/xml');
const entries = xmlDoc.getElementsByTagName('entry');
const items = [];

for (let i = 0; i < entries.length; i++) {
  const idUrl = entries[i].getElementsByTagName('id')[0]?.textContent || '';
  const arxivId = idUrl.split('/abs/').pop();
  if (arxivId) {
    items.push({ json: { arxiv_id: arxivId } });
  }
}
return items;

const papers = $input.all();
const messages = [];

for (const p of papers) {
  const data = p.json;
  if (data.status === 'SUCCESS') {
    const text = `📄 *${data.metadata.title}*\n` +
      `👨‍🔬 Authors: ${data.metadata.authors.slice(0, 3).join(', ')}${data.metadata.authors.length > 3 ? ' et al.' : ''}\n` +
      `📊 Stats: ${data.stats.pages} pages | ${data.equations_count} equations | ${data.stats.citations_count} citations\n\n` +
      `📝 *Abstract:*\n${data.abstract.slice(0, 350)}...\n\n` +
      `🔗 [PDF Link](${data.metadata.source_url})`;
    messages.push({ json: { formatted_message: text, chunks: data.chunks } });
  }
}
return messages;
